import { AgeCredential } from "../types/credential";
import { signCredential } from "./signature";

export async function issueCredential(age: number): Promise<AgeCredential> {
  const credentialId =
    (globalThis as any).crypto && (globalThis as any).crypto.randomUUID
      ? (globalThis as any).crypto.randomUUID()
      : `id-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;

  const issuedAt = Date.now();
  const signature = await signCredential({ credentialId, age, issuedAt });

  return {
    credentialId,
    issuer: "DemoGov",
    age,
    issuedAt,
    signature,
  };
}